components.css:
.ds-btn-primary { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; min-height: 44px; padding: 0.75rem 1rem; border: 0; border-radius: 3px; background: #1b1a17; color: #faf8f4; font: 500 0.9375rem/1.5 "Segoe UI", system-ui, sans-serif; cursor: pointer; transition: background-color 150ms ease-out, color 150ms ease-out; }
.ds-btn-primary:hover { background: #33312c; }
.ds-btn-primary:focus-visible { outline: 2px solid #1b1a17; outline-offset: 2px; }
.ds-btn-primary:active { background: #000000; }
.ds-btn-primary:disabled { opacity: 0.45; cursor: not-allowed; }

.ds-btn-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; min-height: 44px; padding: 0.75rem 1rem; border: 1px solid #c9c3b6; border-radius: 3px; background: transparent; color: #1b1a17; font: 500 0.9375rem/1.5 "Segoe UI", system-ui, sans-serif; cursor: pointer; transition: background-color 150ms ease-out, border-color 150ms ease-out; }
.ds-btn-secondary:hover { background: #f2eee6; border-color: #a8a294; }
.ds-btn-secondary:focus-visible { outline: 2px solid #1b1a17; outline-offset: 2px; }
.ds-btn-secondary:disabled { opacity: 0.45; cursor: not-allowed; }

.ds-text-actions { display: flex; align-items: center; gap: 0.25rem; }
.ds-text-action { display: inline-flex; align-items: center; min-height: 44px; padding: 0 0.5rem; border: 0; border-radius: 2px; background: transparent; color: #1b1a17; font: 400 0.875rem/1.5 "Segoe UI", system-ui, sans-serif; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: #c9c3b6; cursor: pointer; transition: color 150ms ease-out, text-decoration-color 150ms ease-out; }
.ds-text-action:hover { text-decoration-color: #1b1a17; }
.ds-text-action:focus-visible { outline: 2px solid #1b1a17; outline-offset: 2px; }
.ds-text-action--danger { color: #b3261e; text-decoration-color: #e3b0ae; }
.ds-text-action--danger:hover { text-decoration-color: #b3261e; }

.ds-field { display: flex; flex-direction: column; gap: 0.25rem; }
.ds-field__label { color: #55524c; font: 500 0.75rem/1.5 "Segoe UI", system-ui, sans-serif; letter-spacing: 0.04em; text-transform: uppercase; }
.ds-field__input { width: 100%; min-height: 44px; padding: 0.25rem 0; border: 0; border-bottom: 1px solid #c9c3b6; border-radius: 0; background: transparent; color: #1b1a17; font: 400 1rem/1.5 "Segoe UI", system-ui, sans-serif; }
.ds-field__input::placeholder { color: #6b6862; }
.ds-field__input:focus-visible { outline: none; border-bottom-color: #1b1a17; }
.ds-field__input:disabled { color: #6b6862; border-bottom-style: dotted; }

.ds-number { position: relative; display: inline-flex; align-items: center; }
.ds-number__input { width: 8rem; min-height: 44px; padding: 0.25rem 2.5rem 0.25rem 0; border: 0; border-bottom: 1px solid #c9c3b6; border-radius: 0; background: transparent; color: #1b1a17; text-align: right; font: 400 1.125rem/1.5 ui-monospace, "Cascadia Mono", Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
.ds-number__input:focus-visible { outline: none; border-bottom-color: #1b1a17; }
.ds-number__unit { position: absolute; right: 0.5rem; color: #6b6862; font: 400 0.75rem/1.5 "Segoe UI", system-ui, sans-serif; pointer-events: none; }

.ds-chip { display: inline-flex; align-items: center; gap: 0.375rem; padding: 0.125rem 0.5rem; border-radius: 3px; font: 500 0.75rem/1.5 "Segoe UI", system-ui, sans-serif; letter-spacing: 0.01em; white-space: nowrap; }
.ds-chip__glyph { font-size: 0.6em; line-height: 1; }
.ds-chip--energie { background: #fdf0e3; color: #a34f00; }
.ds-chip--warm { background: #fbeceb; color: #c62828; }
.ds-chip--kalt { background: #eaf1fb; color: #1565c0; }

.ds-stripe { display: block; width: 3px; height: 2.5rem; border-radius: 1px; background: #a34f00; }
.ds-stripe--warm { background: #c62828; }
.ds-stripe--kalt { background: #1565c0; }

.ds-nav { display: flex; gap: 0.25rem; border-top: 1px solid #e3ded4; }
.ds-nav__item { display: flex; align-items: center; min-height: 44px; padding: 0.625rem 0.75rem; border-bottom: 2px solid transparent; color: #6b6862; text-decoration: none; font: 500 0.875rem/1.5 "Segoe UI", system-ui, sans-serif; transition: color 150ms ease-out; }
.ds-nav__item:hover { color: #1b1a17; }
.ds-nav__item:focus-visible { outline: 2px solid #1b1a17; outline-offset: 2px; }
.ds-nav__item--active { color: #1b1a17; border-bottom-color: #1b1a17; }

.ds-msg { display: flex; align-items: flex-start; gap: 0.75rem; padding: 0.5rem 0; border-bottom: 1px solid #e3ded4; font: 400 0.875rem/1.4 "Segoe UI", system-ui, sans-serif; }
.ds-msg__glyph { margin-top: 3px; line-height: 1; }
.ds-msg__text { flex: 1; }
.ds-msg--fehler { color: #b3261e; }
.ds-msg--warnung { color: #8a5a00; }
.ds-msg--erfolg { color: #1f6f3f; }
.ds-msg--info { color: #55524c; }
.ds-msg__close { display: inline-flex; align-items: center; justify-content: center; min-width: 44px; min-height: 44px; margin: -0.25rem -0.25rem -0.25rem 0; border: 0; border-radius: 2px; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.ds-msg__close:hover { text-decoration: underline; }
.ds-msg__close:focus-visible { outline: 2px solid #1b1a17; outline-offset: 2px; }

.ds-lauflinie { position: relative; height: 3px; overflow: hidden; background: #e3ded4; }
.ds-lauflinie::after { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 45%; background: #1b1a17; opacity: 0; transform: translateX(-100%); transition: opacity 150ms ease-out; }
.ds-lauflinie--laeuft::after { opacity: 1; animation: ds-lauflinie 1400ms cubic-bezier(0.16, 1, 0.3, 1) infinite; }
@keyframes ds-lauflinie { from { transform: translateX(-100%); } to { transform: translateX(222%); } }
@media (prefers-reduced-motion: reduce) { .ds-lauflinie--laeuft::after { animation-duration: 0.01ms; animation-iteration-count: 1; } }
